// Finite State Machine to search for message boundaries
module FSM(
  input clk,
  input reset,
  input [7:0] in,
  output reg [1:0] state,
  output reg found_start
);
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      found_start <= 1'b0;
    end else begin
      case (state)
        2'b00: if (in[3] == 1'b1) begin state <= 2'b01; found_start <= 1'b1; end
        2'b01: if (in[3] == 1'b0) begin state <= 2'b10; end
        2'b10: if (in[3] == 1'b1) begin state <= 2'b11; found_start <= 1'b1; end
        2'b11: if (in[3] == 1'b0) begin state <= 2'b00; end
      endcase
    end
  end
end

// Datapath to output the 24-bit (3 byte) message
module Datapath(
  input clk,
  input reset,
  input [7:0] in,
  input found_start,
  output reg [23:0] out_bytes,
  output reg done
);
  reg [1:0] state;
  reg [7:0] bytes [0:2];
  reg [2:0] byte_counter;
  FSM fsm(.clk(clk), .reset(reset), .in(in), .state(state), .found_start(found_start));
  always @(posedge clk) begin
    if (reset) begin
      byte_counter <= 3'b000;
      done <= 1'b0;
    end else begin
      if (state == 2'b01 || state == 2'b11) begin
        bytes[byte_counter] <= in;
        byte_counter <= byte_counter + 1;
        if (byte_counter == 3'b111) begin
          out_bytes <= {bytes[0], bytes[1], bytes[2]};
          done <= 1'b1;
        end
      end else begin
        done <= 1'b0;
      end
    end
  end
end

// Top-level module
module TopModule(
  input clk,
  input reset,
  input [7:0] in,
  output reg [23:0] out_bytes,
  output reg done
);
  reg found_start;
  Datapath dp(.clk(clk), .reset(reset), .in(in), .found_start(found_start), .out_bytes(out_bytes), .done(done));
  FSM fsm(.clk(clk), .reset(reset), .in(in), .state(dp.state), .found_start(found_start));
endmodule

