// Datapath: outputs the 24-bit message on each cycle after a successful
// message receipt (done goes high->low->high). The reset is active high
// synchronous. out_bytes is valid whenever done is asserted.
module datapath (
    input  wire        clk,
    input  wire        reset,
    input  wire  [7:0] in,
    output reg  [23:0] out_bytes,
    output reg         done
);
    reg  [23:0] msg;
    reg  [1:0]  byte_count;
    always @(posedge clk) begin
        if (reset) begin
            msg <= 24'h000000;
            byte_count <= 2'b00;
            done <= 1'b0;
        end else begin
            if (byte_count == 2'b00) begin
                if (in[3] == 1'b1) begin
                    msg[23:0] <= {8'h00, in[7:0]};
                    byte_count <= 2'b01;
                    done <= 1'b0;
                end
            end else if (byte_count == 2'b01) begin
                msg[15:0] <= {8'h00, in[7:0]};
                byte_count <= 2'b10;
                done <= 1'b0;
            end else if (byte_count == 2'b10) begin
                msg[7:0] <= in[7:0];
                byte_count <= 2'b11;
                done <= 1'b0;
            end else if (byte_count == 2'b11) begin
                byte_count <= 2'b00;
                done <= 1'b1;
            end
        end
    end
    always @(posedge clk) begin
        if (reset) out_bytes <= 24'h000000;
        else if (done) out_bytes <= msg;
    end
endmodule

