// Finite state machine that discards bytes until we see one with in[3]=1.
// Once this byte is received, we assume it is byte 1 of a message, and the
// FSM signals the receipt of a message once all 3 bytes have been received.
module fsm (
  input  clk,
  input  reset,
  input  [7:0] in,
  output reg  done,
  output reg  [15:0] wait_count
);
  reg  [2:0] state;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'd0;
      done <= 1'b0;
      wait_count <= 16'd0;
    end else begin
      case (state)
        3'd0: begin
          if (in[3] == 1'b1) state <= 3'd1;
          else wait_count <= wait_count + 16'd1;
        end
        3'd1: begin
          if (in[3] == 1'b0) state <= 3'd2;
          else wait_count <= wait_count + 16'd1;
